[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* CommerceForge Dev Docs — Global Styles */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2129;
  --bg-card: #161b22;
  --border-color: #30363d;
  --border-hover: #475f91;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00c98b;
  --accent-blue: #475f91;
  --accent-cyan: #00d4ff;
  --accent-purple: #a78bfa;
  --accent-orange: #f97316;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --transition: 0.2s ease;
  --max-width: 1280px;
  --sidebar-width: 260px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

code, pre { font-family: var(--font-mono); }

/* ─── Top Navigation ─── */
.topnav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.topnav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 60px;
}

.topnav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.topnav-logo svg { flex-shrink: 0; }

.topnav-links {
  display: flex;
  align-items: center;
  gap: 8px;
  list-style: none;
}

.topnav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 6px;
  transition: all var(--transition);
}

.topnav-links a:hover,
.topnav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.topnav-utils {
  display: flex;
  align-items: center;
  gap: 8px;
}

.topnav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 12px;
  color: var(--text-muted);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.topnav-search:hover { border-color: var(--border-hover); }

.btn-login {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 6px 16px;
  border-radius: 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-login:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

/* ─── Hero Section ─── */
.hero {
  padding: 80px 24px 60px;
  text-align: center;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 700px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: #0d1117;
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 12px 24px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: #0d1117;
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0, 229, 160, 0.3);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  color: var(--text-primary);
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 12px 24px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all var(--transition);
}

.btn-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  color: var(--accent);
  font-weight: 600;
  font-size: 0.875rem;
  padding: 8px 0;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-ghost:hover { color: var(--accent-hover); }
.btn-ghost::after { content: ' →'; }

/* ─── Section Utilities ─── */
.section {
  padding: 60px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: 1rem;
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
  margin-bottom: 40px;
}

/* ─── Card Grid ─── */
.card-grid {
  display: grid;
  gap: 20px;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-2 { grid-template-columns: repeat(2, 1fr); }
.card-grid-4 { grid-template-columns: repeat(4, 1fr); }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

.card:hover::before { opacity: 1; }

.card-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 1.25rem;
}

.card-icon-green { background: rgba(0, 229, 160, 0.12); color: var(--accent); }
.card-icon-blue { background: rgba(0, 212, 255, 0.12); color: var(--accent-cyan); }
.card-icon-purple { background: rgba(167, 139, 250, 0.12); color: var(--accent-purple); }
.card-icon-orange { background: rgba(249, 115, 22, 0.12); color: var(--accent-orange); }

.card h3 {
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.card-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
}

.card-link:hover { color: var(--accent-hover); }

/* ─── Product Cards (Home) ─── */
.product-card {
  padding: 36px 28px;
  display: flex;
  flex-direction: column;
}

.product-card .card-link { margin-top: auto; }

/* ─── CLI Setup Section ─── */
.cli-section {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.cli-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 440px;
}

.cli-info {
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.cli-info h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.cli-info p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.9375rem;
}

.cli-interactive {
  background: var(--bg-tertiary);
  border-left: 1px solid var(--border-color);
  padding: 32px;
  display: flex;
  flex-direction: column;
}

/* Accordion */
.accordion { display: flex; flex-direction: column; gap: 8px; }

.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active { border-color: var(--accent); }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--bg-secondary);
  border: none;
  color: var(--text-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition);
  font-family: var(--font-sans);
}

.accordion-trigger:hover { background: var(--bg-card); }

.accordion-trigger .chevron {
  transition: transform 0.3s ease;
  flex-shrink: 0;
}

.accordion-item.active .accordion-trigger .chevron {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-body {
  max-height: 500px;
}

.accordion-content {
  padding: 16px;
}

.accordion-content ol {
  list-style: decimal;
  padding-left: 20px;
  margin-bottom: 16px;
}

.accordion-content li {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 6px;
  line-height: 1.5;
}

/* Package Manager Tabs */
.pkg-tabs {
  display: flex;
  gap: 0;
  margin-bottom: 0;
  border-bottom: 1px solid var(--border-color);
}

.pkg-tab {
  padding: 8px 16px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 0.8125rem;
  font-weight: 600;
  font-family: var(--font-mono);
  cursor: pointer;
  transition: all var(--transition);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.pkg-tab:hover { color: var(--text-secondary); }
.pkg-tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.code-block {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 14px 16px;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  color: var(--accent);
  overflow-x: auto;
  position: relative;
  margin-top: 0;
}

.code-block .prompt { color: var(--text-muted); user-select: none; }

.code-block-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.code-label {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-top: 12px;
  margin-bottom: 4px;
}

/* ─── Launch CTA ─── */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 36px;
  transition: all 0.3s ease;
}

.launch-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ─── Community ─── */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all 0.3s ease;
  display: block;
}

.community-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text-primary);
}

.community-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ─── Footer ─── */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 40px;
  margin-top: 40px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
}

.footer-col h5 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 10px; }

.footer-col a {
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ─── Docs Layout (Sidebar + Content) ─── */
.docs-layout {
  display: flex;
  max-width: var(--max-width);
  margin: 0 auto;
  min-height: calc(100vh - 60px);
}

.docs-sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
  padding: 24px 16px;
  position: sticky;
  top: 60px;
  height: calc(100vh - 60px);
  overflow-y: auto;
  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
}

.docs-sidebar.collapsed {
  width: 0;
  padding: 24px 0;
  opacity: 0;
  overflow: hidden;
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-muted);
  cursor: pointer;
  margin-bottom: 20px;
  transition: all var(--transition);
}

.sidebar-toggle:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.sidebar-section {
  margin-bottom: 24px;
}

.sidebar-section h4 {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 8px;
}

.sidebar-section ul { list-style: none; }

.sidebar-section li a {
  display: block;
  padding: 6px 8px;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  border-radius: 4px;
  transition: all var(--transition);
}

.sidebar-section li a:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-section li a.active {
  color: var(--accent);
  background: rgba(0, 229, 160, 0.08);
}

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px;
  transition: padding 0.3s ease;
}

.docs-content .hero {
  padding: 40px 0;
  text-align: left;
}

.docs-content .hero h1 { font-size: clamp(1.75rem, 3vw, 2.5rem); }

.docs-content .section {
  padding: 40px 0;
}

/* ─── Interior Page Grid ─── */
.interior-grid {
  display: grid;
  gap: 16px;
}

.interior-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }
.interior-grid.cols-3 { grid-template-columns: repeat(3, 1fr); }

.interior-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all 0.3s ease;
}

.interior-card:hover {
  border-color: var(--border-hover);
}

.interior-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.interior-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ─── Protocol Actors Diagram ─── */
.actors-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  position: relative;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  text-align: center;
  transition: all 0.3s ease;
}

.actor-card:hover { border-color: var(--border-hover); }

.actor-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-size: 1.25rem;
}

.actor-card h4 { font-size: 0.9375rem; font-weight: 600; margin-bottom: 4px; }
.actor-card p { font-size: 0.75rem; color: var(--text-secondary); }

/* ─── Coming Soon Badge ─── */
.badge-soon {
  display: inline-block;
  background: rgba(249, 115, 22, 0.15);
  color: var(--accent-orange);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  border-radius: 20px;
  margin-left: 8px;
}

/* ─── Support Page ─── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.3s ease;
}

.support-card:hover { border-color: var(--border-hover); }

.support-card h3 {
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.contact-box {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  margin-top: 32px;
}

.contact-box h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.contact-box p {
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .actors-grid { grid-template-columns: repeat(2, 1fr); }
  .cli-inner { grid-template-columns: 1fr; }
  .cli-interactive { border-left: none; border-top: 1px solid var(--border-color); }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
  .docs-sidebar { display: none; }
  .docs-content { padding: 24px; }
  .interior-grid.cols-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .topnav-search { display: none; }
  .mobile-menu-btn { display: block; }

  .topnav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 60px;
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 16px 24px;
    gap: 4px;
  }

  .hero { padding: 48px 24px 36px; }
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .card-grid-3, .card-grid-2, .card-grid-4 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .actors-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; }
  .section { padding: 40px 24px; }
  .interior-grid.cols-2, .interior-grid.cols-3 { grid-template-columns: 1fr; }
}
